function longestSquareStreak(nums) {
  const seen = new Set(nums);
  let best = 0;

  for (const start of seen) {
    let length = 0;
    let current = start;
    while (seen.has(current)) {
      length++;
      current = current * current;
    }
    best = Math.max(best, length);
  }
  return best >= 2 ? best : -1;
}

