function longestSquareStreak(nums) {
  const values = [...new Set(nums)].sort((a, b) => a - b);
  const chain = values.map(() => 1);
  let answer = -1;
  for (let j = 0; j < values.length; j++) {
    for (let i = 0; i < j; i++) {
      if (values[i] * values[i] === values[j]) chain[j] = Math.max(chain[j], chain[i] + 1);
    }
    if (chain[j] >= 2) answer = Math.max(answer, chain[j]);
  }
  return answer;
}

