function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 2 + Math.floor(rand() * 9);
  const limit = large ? 100000 : 300;
  const plantRate = large ? rand() * 0.02 : 0.4;
  const nums = [];
  while (nums.length < n) {
    if (rand() < plantRate) {
      // Plant part of a squaring chain so that streaks of several lengths appear.
      let value = 2 + Math.floor(rand() * (large ? 315 : 15));
      while (value <= 100000 && nums.length < n) {
        nums.push(value);
        if (rand() < 0.3) break;
        value = value * value;
      }
    } else {
      nums.push(2 + Math.floor(rand() * (limit - 1)));
    }
  }
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
